    test(
        "upsertConnectorProjectConnection answers 400 with its declared error body",
        () async {
      SdkConfig.getConfig().baseUrl = '$baseUrl/__mockStatus/400';
      addTearDown(() => SdkConfig.getConfig().baseUrl = baseUrl);
      final SdkHttpError error;
      try {
        await sdk_methods_21.upsertConnectorProjectConnection(
          config,
          connector: (jsonDecode("\"connector\"") as String),
          projectId: (jsonDecode("\"project-1\"") as String),
          environments: (jsonDecode("[\"env_\"]") as List)
              .map((element) => (element as String))
              .toList(),
          teamId: SdkPresent<String>(
              (jsonDecode("\"team_1a2b3c4d5e6f7g8h9i0j1k2l\"") as String)),
          slug: SdkPresent<String>(
              (jsonDecode("\"my-team-url-slug\"") as String)),
        );
        fail('did not raise its declared error');
      } on SdkHttpError catch (caught) {
        error = caught;
      }
      expect(error.statusCode, 400);
      expect(
        mismatch(
            normal(error.data),
            SdkUtils.decodeJson(
                "{\"error\":{\"code\":\"code\",\"message\":\"example text\"}}")),
        isNull,
      );
    });

